  });
  if (activeKey && edgeMap[activeKey]) {
    drawEdge(backing, edgeMap[activeKey], status === 'improved' ? '#8e8e8e' : '#d6d6d6', status === 'improved' ? 19 : 10, false, status === 'unchanged' ? 0.75 : 0.95);
  }

  var edgeLayer = g.group();
  edges.forEach(function (e) { drawEdge(edgeLayer, e, '#000', 2.2, true, 1); });

  var weightLayer = g.group();
  edges.forEach(function (e) {
