  });

  var nodeLayer = g.group();
  ['s', 't', 'y', 'x', 'z'].forEach(function (id) {
    var n = nodes[id];
    var wrong = lastRunCorrect === false && currentSource === 'run' && frameIndex === replayFrames.length - 1 && !isExpectedNode(id, dist, pred);
    nodeLayer.circle(62).center(n.x, n.y).fill(wrong ? '#ffd7d7' : '#dedede').stroke({ color: '#000', width: 2 });
    nodeLayer.text(fmt(dist[id])).font({
      family: 'Times New Roman, serif',
      size: 34,
      anchor: 'middle',
      leading: 1
    }).center(n.x, n.y + 1);
    var lx = n.x, ly = n.y;
    if (id === 's') { lx = n.x - 67; ly = n.y + 2; }
    if (id === 't') { lx = n.x; ly = n.y - 54; }
    if (id === 'y') { lx = n.x; ly = n.y + 58; }
    if (id === 'x') { lx = n.x; ly = n.y - 54; }
    if (id === 'z') { lx = n.x; ly = n.y + 58; }
    nodeLayer.text(id).font({
      family: 'Times New Roman, serif',
      size: 32,
      style: 'italic',
      anchor: 'middle',
      leading: 1
    }).center(lx, ly);
    nodeLayer.last().css('cursor', 'pointer')
      .on('mousemove', function (ev) { showTooltip('vertex ' + id + ': current estimate d[' + id + '] = ' + fmt(dist[id]), ev); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Vertex ' + id, 'The number inside the vertex is Bellman-Ford’s current best distance estimate from source s. It can decrease when a better path is found.');
      });
  });

  var info = g.group();
  var panel = frame.panel || '';
  var pass = frame.pass != null ? frame.pass : (frame.state ? frame.state.pass : 0);
  var changes = frame.changes != null ? frame.changes : (frame.state ? frame.state.changes : 0);
  info.text(panel).font({ family: 'Times New Roman, serif', size: 34, anchor: 'middle' }).center(380, 492);
  var passText = pass === 0 ? 'initial estimates' : 'pass ' + pass + '   successful changes: ' + changes;
  info.text(passText).font({ family: 'sans-serif', size: 16, anchor: 'start' }).move(22, 18);

  var candidate = frame.candidate || (frame.state && frame.state.candidate);
  var msg = frame.message || '';
  if (candidate || active) {
    var line = active ? 'active: ' + active[0] + '→' + active[1] : 'active edge';
    if (candidate) line += '    candidate: ' + String(candidate).replace(/-/g, '−');
    makeLabel(info, 410, 22, line, 16, false);
  }
  if (lastRunCorrect === false && currentSource === 'run' && frameIndex === replayFrames.length - 1) {
    info.text('Wrong final state: red vertices disagree with the expected shortest-path solution.')
      .font({ family: 'sans-serif', size: 15, anchor: 'start' })
      .fill('#a40000').move(22, 45);
  } else if (lastRunCorrect === true && currentSource === 'run' && frameIndex === replayFrames.length - 1) {
    info.text('Correct final state: predecessor edges form s→y→x→t→z.')
      .font({ family: 'sans-serif', size: 15, anchor: 'start' })
      .fill('#116611').move(22, 45);
  }
}

function isExpectedNode(id, dist, pred) {
  var ed = { s: 0, t: 2, x: 4, y: 7, z: -2 };
  var ep = { t: 'x', x: 'y', y: 's', z: 't' };
  if (Math.abs((dist[id] || 0) - ed[id]) > 1e-9) return false;
  if (id !== 's' && pred[id] !== ep[id]) return false;
  return true;
}

function updateCaption(frame) {
  var cap = document.getElementById('frameCaption');
  if (!cap) return;
  cap.textContent = frame && frame.message ? frame.message : 'Use the steps above, or edit relax(u,v,w) and run it.';
}

function updateLog() {
  var log = document.getElementById('traceLog');
  if (!log) return;
  if (currentSource === 'demo') {
    log.value = demoSteps.map(function (s, i) {
      return (i === demoIndex ? '▶ ' : '  ') + (i + 1) + '. ' + s.title;
    }).join('\\n');
  } else {
    var start = Math.max(0, frameIndex - 10);
    log.value = replayFrames.slice(start, frameIndex + 1).map(function (f, i) {
      return (start + i + 1) + '. ' + (f.message || f.kind || 'frame');
    }).join('\\n');
    log.scrollTop = log.scrollHeight;
  }
}

function showDemoStep(i) {
  stopPlay();
  currentSource = 'demo';
