  if (e.u === 'z' && e.v === 's') return 'M 580 381 L 130 259';
  return '';
}

function makeLabel(parent, x, y, text, size, italic) {
  var group = parent.group();
  var t = group.text(text).font({
    family: 'Times New Roman, serif',
    size: size || 31,
    anchor: 'middle',
    leading: 1
  }).center(x, y);
  if (italic) t.font({ style: 'italic' });
  var b = t.bbox();
  group.rect(b.width + 8, b.height + 4).fill('#fff').opacity(0.88).center(x, y).back();
  return group;
}

function drawEdge(parent, e, color, width, marker, opacity) {
  var p = parent.path(edgePath(e)).fill('none').stroke({
    color: color || '#000',
    width: width || 2,
    linecap: 'round',
    linejoin: 'round'
  }).opacity(opacity == null ? 1 : opacity);
  if (marker) p.marker('end', arrowMarker);
  p.css('cursor', 'pointer')
    .on('mousemove', function (ev) {
      showTooltip(e.u + '→' + e.v + ', weight ' + fmt(e.w), ev);
    })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Relax edge ' + e.u + '→' + e.v,
        'Relaxation tests whether d[' + e.u + '] + ' + fmt(e.w) +
        ' is smaller than d[' + e.v + ']. If so, Bellman-Ford updates the destination estimate and predecessor.');
    });
  return p;
}

function predEdges(pred) {
  var out = [];
  Object.keys(pred || {}).forEach(function (v) {
    if (pred[v]) out.push(pred[v] + '>' + v);
  });
  return out;
}

