  updateCaption(s.frame);
  updateLog();
  renderGraph(s.frame);
}

function prevStep() { showDemoStep(demoIndex - 1); }
function nextStep() { showDemoStep(demoIndex + 1); }

function loadSample(which) {
  var box = document.getElementById('relaxImplementationCode');
  if (which === 'buggy') box.value = BUGGY_CODE;
  else if (which === 'starter') box.value = STARTER_CODE;
  else box.value = SAMPLE_CODE;
}

function frameToDrawable(f) {
  if (!f) return null;
  var st = f.state || {};
  return {
    pass: st.pass,
    changes: st.changes,
    dist: st.dist,
    pred: st.pred,
    activeEdge: st.activeEdge,
    status: st.lastStatus,
    candidate: st.candidate,
    message: f.message
  };
}

function showReplayFrame(i) {
  if (!replayFrames.length) return;
  currentSource = 'run';
  frameIndex = Math.max(0, Math.min(replayFrames.length - 1, i));
  var f = replayFrames[frameIndex];
  document.getElementById('frameCounter').textContent = (frameIndex + 1) + ' of ' + replayFrames.length;
  updateCaption(f);
  updateLog();
  renderGraph(frameToDrawable(f));
}

function firstFrame() { stopPlay(); showReplayFrame(0); }
function prevFrame() { stopPlay(); showReplayFrame(frameIndex - 1); }
function nextFrame() { stopPlay(); showReplayFrame(frameIndex + 1); }

function stopPlay() {
  if (playTimer) clearTimeout(playTimer);
  playTimer = null;
  var b = document.getElementById('playBtn');
  if (b) b.textContent = '▶';
}

function togglePlay() {
  if (!replayFrames.length) return;
  if (playTimer) { stopPlay(); return; }
  document.getElementById('playBtn').textContent = '❚❚';
  function tick() {
    if (frameIndex >= replayFrames.length - 1) { stopPlay(); return; }
    showReplayFrame(frameIndex + 1);
    var speed = +document.getElementById('speedInput').value || 1;
    playTimer = setTimeout(tick, 650 / speed);
  }
  tick();
}

function expectedOK(finalState) {
  if (!finalState || !finalState.dist || !finalState.pred) return false;
  var d = finalState.dist, p = finalState.pred;
  return Math.abs(d.s - 0) < 1e-9 &&
    Math.abs(d.t - 2) < 1e-9 &&
    Math.abs(d.x - 4) < 1e-9 &&
    Math.abs(d.y - 7) < 1e-9 &&
    Math.abs(d.z - (-2)) < 1e-9 &&
    p.y === 's' && p.x === 'y' && p.t === 'x' && p.z === 't';
}

function workerSource(userCode) {
  return `
var vertices = ['s','t','x','y','z'];
var edgeOrder = [
  ['t','x',5], ['t','y',8], ['t','z',-4], ['x','t',-2],
  ['y','x',-3], ['y','z',9], ['z','x',7], ['z','s',2],
  ['s','t',6], ['s','y',7]
];
var distValues = { s:0, t:Infinity, x:Infinity, y:Infinity, z:Infinity };
var predValues = {};
var frames = [];
var opCount = 0;
var maxOps = 800;
var maxFrames = 1000;
var pass = 0;
var changes = 0;
var activeEdge = null;
var candidate = null;
var lastStatus = null;
function fmt(v){ return v===Infinity ? '∞' : String(v).replace('-', '−'); }
function copyDist(){ return {s:distValues.s,t:distValues.t,x:distValues.x,y:distValues.y,z:distValues.z}; }
function copyPred(){ var p={}; Object.keys(predValues).forEach(function(k){p[k]=predValues[k];}); return p; }
function validVertex(v){ return vertices.indexOf(v) >= 0; }
function assertOp(){
  opCount++;
  if (opCount > maxOps) throw new Error('operation cap hit: relaxation appears not to terminate');
  if (frames.length > maxFrames) throw new Error('frame cap hit: too many recorded API operations');
}
function snap(kind, indices, message){
  frames.push({
    kind: kind,
    indices: indices || [],
    message: message || kind,
    state: {
      dist: copyDist(),
      pred: copyPred(),
      pass: pass,
      changes: changes,
      activeEdge: activeEdge ? [activeEdge[0], activeEdge[1]] : null,
      candidate: candidate,
      lastStatus: lastStatus
    }
  });
}
var dist = new Proxy({}, {
  get: function(target, prop) {
    if (typeof prop === 'symbol') return undefined;
    if (!validVertex(prop)) throw new Error('dist[' + String(prop) + '] is not a vertex');
    assertOp();
    snap('read', [String(prop)], 'read dist[' + prop + '] = ' + fmt(distValues[prop]));
    return distValues[prop];
  },
  set: function(){ throw new Error('Use setDist(v,value); direct assignment to dist is disabled.'); }
});
function less(a,b){
  assertOp();
  candidate = a;
  var result = a < b;
  snap('compare', activeEdge ? [activeEdge[0], activeEdge[1]] : [], 'compare candidate ' + fmt(a) + ' with current estimate ' + fmt(b) + ' → ' + result);
  return result;
}
function setDist(v, value){
  assertOp();
  if (!validVertex(v)) throw new Error('setDist: unknown vertex ' + v);
  if (typeof value !== 'number') throw new Error('setDist: value for ' + v + ' must be numeric');
  distValues[v] = value;
  changes++;
  snap('setDist', [v], 'set dist[' + v + '] = ' + fmt(value) + ' and count one successful relaxation');
}
function setPred(v,u){
  assertOp();
  if (!validVertex(v) || !validVertex(u)) throw new Error('setPred: unknown vertex');
  predValues[v] = u;
  snap('setPred', [u,v], 'set predecessor of ' + v + ' to ' + u);
}
function markEdge(u,v,status){
  assertOp();
  if (!validVertex(u) || !validVertex(v)) throw new Error('markEdge: unknown vertex');
  lastStatus = status === 'improved' ? 'improved' : 'unchanged';
  snap('markEdge', [u,v], 'mark ' + u + '→' + v + ' as ' + lastStatus);
}
function note(text){
  assertOp();
  snap('note', [], String(text));
}
Object.freeze({ dist: dist, less: less, setDist: setDist, setPred: setPred, markEdge: markEdge, note: note });
try {
  var makeRelax = new Function(${JSON.stringify(userCode)} + '\\n; return (typeof relax === "function") ? relax : null;');
  var relaxFn = makeRelax();
  if (typeof relaxFn !== 'function') throw new Error('Missing entry point: define function relax(u, v, w).');
  snap('init', [], 'start with dist.s = 0 and all other distances = ∞');
  for (pass = 1; pass <= 4; pass++) {
    changes = 0;
    snap('passStart', [], 'begin pass ' + pass + ': relax every directed edge once');
    for (var i = 0; i < edgeOrder.length; i++) {
      activeEdge = edgeOrder[i];
      candidate = null;
      lastStatus = 'relaxing';
      snap('edge', [activeEdge[0], activeEdge[1]], 'try relaxing ' + activeEdge[0] + '→' + activeEdge[1] + ' with weight ' + fmt(activeEdge[2]));
      relaxFn(activeEdge[0], activeEdge[1], activeEdge[2]);
    }
    activeEdge = null;
    candidate = null;
    lastStatus = null;
    snap('passEnd', [], 'end pass ' + pass + ' with ' + changes + ' successful distance update(s)');
  }
  self.postMessage({ ok:true, frames:frames, final:{dist:copyDist(), pred:copyPred()} });
} catch (e) {
  snap('error', [], 'Error: ' + (e && e.message ? e.message : e));
  self.postMessage({ ok:false, frames:frames, error:(e && e.message ? e.message : String(e)), final:{dist:copyDist(), pred:copyPred()} });
}
`;
}

function runStudentCode() {
  stopPlay();
  var code = document.getElementById('relaxImplementationCode').value;
  var status = document.getElementById('runStatus');
  var runBtn = document.getElementById('runBtn');
  status.textContent = 'running…';
  status.style.color = '#444';
  runBtn.disabled = true;
  replayFrames = [];
  frameIndex = 0;
  currentSource = 'run';
  lastRunCorrect = null;
  lastRunError = false;

  var blob = new Blob([workerSource(code)], { type: 'application/javascript' });
  var url = URL.createObjectURL(blob);
  var worker = new Worker(url);
  var done = false;
  var timer = setTimeout(function () {
    if (done) return;
    done = true;
    worker.terminate();
    URL.revokeObjectURL(url);
    runBtn.disabled = false;
    lastRunCorrect = false;
    lastRunError = true;
    status.textContent = 'error: timeout';
    status.style.color = '#a40000';
    replayFrames = [{
      kind: 'error',
      message: 'Error: time limit exceeded; check for an infinite loop in relax.',
      state: { dist: { s: 0, t: Infinity, x: Infinity, y: Infinity, z: Infinity }, pred: {}, pass: 0, changes: 0, activeEdge: null }
    }];
    showReplayFrame(0);
  }, 1800);

  worker.onmessage = function (ev) {
    if (done) return;
    done = true;
    clearTimeout(timer);
    worker.terminate();
    URL.revokeObjectURL(url);
    runBtn.disabled = false;
    replayFrames = ev.data.frames && ev.data.frames.length ? ev.data.frames : [{
      kind: 'error',
      message: 'No frames were recorded.',
      state: { dist: { s: 0, t: Infinity, x: Infinity, y: Infinity, z: Infinity }, pred: {}, pass: 0, changes: 0, activeEdge: null }
    }];
    if (!ev.data.ok) {
      lastRunCorrect = false;
      lastRunError = true;
      status.textContent = 'error';
      status.style.color = '#a40000';
    } else if (expectedOK(ev.data.final)) {
      lastRunCorrect = true;
      lastRunError = false;
      status.textContent = 'correct';
      status.style.color = '#116611';
    } else {
      lastRunCorrect = false;
      lastRunError = false;
      status.textContent = 'wrong answer';
      status.style.color = '#a40000';
    }
    showReplayFrame(0);
  };

  worker.onerror = function (e) {
    if (done) return;
    done = true;
    clearTimeout(timer);
    worker.terminate();
    URL.revokeObjectURL(url);
    runBtn.disabled = false;
    lastRunCorrect = false;
    lastRunError = true;
    status.textContent = 'error';
    status.style.color = '#a40000';
    replayFrames = [{
      kind: 'error',
      message: 'Worker error: ' + (e.message || 'unknown error'),
      state: { dist: { s: 0, t: Infinity, x: Infinity, y: Infinity, z: Infinity }, pred: {}, pass: 0, changes: 0, activeEdge: null }
    }];
    showReplayFrame(0);
  };
}

showDemoStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Bellman-Ford finds shortest paths by repeatedly relaxing every directed edge, allowing distance estimates to propagate one edge farther per pass and to decrease again when negative-weight edges become reachable.
KEY INSIGHT (what students should walk away understanding): Bellman-Ford works because each pass lets improved estimates travel one more edge along a shortest path, so even negative edges are handled as long as repeated relaxation is allowed to converge.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "Bellman-Ford finds shortest paths by repeatedly relaxing every directed edge, allowing distance estimates to propagate one edge farther per pass and to decrease again when negative-weight edges become reachable.",
  "figureType": "network_diagram",
  "elements": [
    "directed weighted graph with five circular vertices s, t, x, y, and z",
    "vertex s at the left with external label 's' and internal distance estimate",
    "vertex t in the upper center-left with external label 't' and internal distance estimate",
    "vertex y in the lower center-left with external label 'y' and internal distance estimate",
    "vertex x in the upper right with external label 'x' and internal distance estimate",
    "vertex z in the lower right with external label 'z' and internal distance estimate",
    "directed edge s→t labeled 6",
    "directed edge s→y labeled 7",
    "directed edge t→x labeled 5, drawn as the upper curved arrow",
    "directed edge x→t labeled −2, drawn as the lower curved arrow back to t",
    "directed edge t→y labeled 8",
    "directed edge t→z labeled −4",
    "directed edge y→x labeled −3",
    "directed edge y→z labeled 9",
    "directed edge z→x labeled 7",
    "directed edge z→s labeled 2",
    "thin black arrows for all graph edges",
    "edge-weight labels placed near their corresponding arrows",
    "large gray highlight backing for the edge currently relaxed successfully",
    "persistent gray predecessor-tree highlights showing the current best-known predecessor edges",
    "current pass label corresponding to panels (a) through (e)",
    "distance-change counter for the current pass",
    "candidate-distance annotation for the active relaxation attempt",
    "final shortest-path tree highlight s→y→x→t→z"
  ],
  "interactions": [
    {
      "id": "relaxImplementation",
      "type": "code_editor",
      "label": "Implement Bellman-Ford relaxation",
      "entry_point": "relax(u, v, w)",
      "api": [
        {
          "op": "dist[v]",
          "does": "read the current shortest-path estimate for vertex v; initially dist.s = 0 and all other vertices are Infinity"
        },
        {
          "op": "less(a, b)",
          "does": "returns true when a < b and records the comparison as the current relaxation test"
        },
        {
          "op": "setDist(v, value)",
          "does": "updates dist[v], changes the number inside vertex v, and increments the current pass's distance-change counter"
        },
        {
          "op": "setPred(v, u)",
          "does": "sets u as v's predecessor and redraws the gray predecessor highlight entering v"
        },
        {
          "op": "markEdge(u, v, status)",
          "does": "marks the relaxed edge as 'improved' or 'unchanged' for the replay frame"
        },
        {
          "op": "note(text)",
          "does": "adds a learner-authored explanation note to the current replay frame"
        }
      ],
      "frame": "Each recorded frame shows the whole five-vertex directed graph, the active edge being relaxed, the candidate value dist[u] + w, all current distance labels, predecessor highlights, the pass number, and the number of successful distance updates in that pass.",
      "input": {
        "label": "Fixed Bellman-Ford instance",
        "default": "Initial distances: s=0, t=x=y=z=∞. Run 4 passes over edges in this order: t→x 5, t→y 8, t→z −4, x→t −2, y→x −3, y→z 9, z→x 7, z→s 2, s→t 6, s→y 7."
      },
      "sample_code": "function relax(u, v, w) {\n  const candidate = dist[u] + w;\n  if (less(candidate, dist[v])) {\n    setDist(v, candidate);\n    setPred(v, u);\n    markEdge(u, v, \"improved\");\n  } else {\n    markEdge(u, v, \"unchanged\");\n  }\n}",
      "buggy_code": "function relax(u, v, w) {\n  // BUG: extends the path from v instead of from u.\n  const candidate = dist[v] + w;\n  if (less(candidate, dist[v])) {\n    setDist(v, candidate);\n    setPred(v, u);\n    markEdge(u, v, \"improved\");\n  } else {\n    markEdge(u, v, \"unchanged\");\n  }\n}",
      "success_check": "After 4 passes the distances must be dist.s = 0, dist.t = 2, dist.x = 4, dist.y = 7, dist.z = −2, with predecessor edges s→y, y→x, x→t, and t→z forming the final shortest-path tree.",
      "teaches": "A correct relaxation step locally compares one candidate path against the current estimate; repeated in edge-order passes, these local updates propagate shortest-path information through the graph until the final predecessor tree emerges"
    }
  ],
  "demo_steps": [
    {
      "title": "Initialize estimates",
      "narration": "The source vertex s starts at distance 0, while every other vertex starts at ∞ because no paths from s have been discovered yet. All edges are present, but no predecessor tree exists.",
      "state": {}
    },
    {
      "title": "Pass 1: discover neighbors of s",
      "narration": "During the first full edge pass, only the late relaxations s→t and s→y improve distances, producing d[t]=6 and d[y]=7. The first gray predecessor edges show the best known one-edge paths from s.",
      "state": {}
    },
    {
      "title": "Pass 2: propagate through t and y",
      "narration": "Now that t and y have finite estimates, their outgoing edges can improve other vertices. The algorithm reaches x with final estimate 4 through y→x and reaches z with estimate 2 through t→z.",
      "state": {}
    },
    {
      "title": "Pass 3: a negative edge lowers t",
      "narration": "Because x is now known to have distance 4, relaxing x→t with weight −2 improves t from 6 down to 2. This shows why Bellman-Ford must keep making passes even after a vertex already has a finite estimate.",
      "state": {}
    },
    {
      "title": "Pass 4: final improvement reaches z",
      "narration": "With t improved to 2, the next pass relaxes t→z with weight −4 and lowers z to −2. The final predecessor chain s→y→x→t→z is the shortest-path tree.",
      "state": {}
    }
  ],
  "keyInsight": "Bellman-Ford works because each pass lets improved estimates travel one more edge along a shortest path, so even negative edges are handled as long as repeated relaxation is allowed to converge.",
  "reconstructionNotes": "Use the same five-node layout as the textbook figure: s on the far left, t above y near the center, and x above z on the right. Draw all edges as thin black arrows with clear weight labels, including the paired curved arrows between t and x. Show distance estimates inside light-gray circular nodes. During code replay, flash the active edge; when relaxation succeeds, place a thick gray backing under that edge and update the destination node's number. Maintain a persistent gray predecessor-tree overlay after each successful update so the learner can see the evolving tree: first s→t and s→y, then y→x and t→z, then x→t replaces s→t, and finally t→z leads to z=−2. Include a pass/change counter beside the graph rather than recreating five static panels at once."
}

