function renderSingle(frame, opts) {
  opts = opts || {};
  draw.viewbox(0, 0, 760, 520);
  root.clear();
  var g = drawPanel(root, frame, { overview: false, fontScale: 1.25, wrongFinal: opts.wrongFinal });
  g.scale(1.86).translate(43, 28);
  if (opts.annotate) {
    var label = frame.pass === 0 ? 'initial estimates' : 'pass ' + frame.pass + '    successful changes: ' + (frame.changes || 0);
    addText(root, label, 18, 18, 15, { family: 'sans-serif', anchor: 'start' });
    if (frame.activeEdge) {
      var line = 'active: ' + frame.activeEdge[0] + '→' + frame.activeEdge[1];
      if (frame.candidate != null) line += '    candidate: ' + minusText(frame.candidate);
      addText(root, line, 18, 43, 15, { family: 'sans-serif', anchor: 'start', halo: 3 });
    }
    if (opts.wrongFinal) {
      addText(root, 'Wrong final state: red vertices disagree with the expected shortest-path solution.', 18, 68, 14, { family: 'sans-serif', anchor: 'start', fill: '#a40000', halo: 3 });
    } else if (opts.correctFinal) {
      addText(root, 'Correct final state: predecessor edges form s→y→x→t→z.', 18, 68, 14, { family: 'sans-serif', anchor: 'start', fill: '#116611', halo: 3 });
