function updateCaption(frame) {
  document.getElementById('frameCaption').textContent = frame && frame.message ? frame.message : 'Use the overview or step controls, or edit relax(u,v,w) and run it.';
}

function updateLog() {
  var log = document.getElementById('traceLog');
  if (!log) return;
  if (currentSource === 'overview') {
    log.value = demoSteps.map(function (s, i) { return (i + 1) + '. ' + s.title; }).join('\n');
  } else if (currentSource === 'demo') {
    log.value = demoSteps.map(function (s, i) { return (i === demoIndex ? '▶ ' : '  ') + (i + 1) + '. ' + s.title; }).join('\n');
  } else {
    var start = Math.max(0, frameIndex - 10);
    log.value = replayFrames.slice(start, frameIndex + 1).map(function (f, i) {
      return (start + i + 1) + '. ' + (f.message || f.kind || 'frame');
    }).join('\n');
    log.scrollTop = log.scrollHeight;
  }
}

