function fmt(v) {
  if (v === Infinity || v === 'Infinity') return '∞';
  if (v === -Infinity) return '−∞';
  if (typeof v === 'number') return String(v).replace('-', '−');
  return String(v);
}

function minusText(s) {
  return String(s).replace(/-/g, '−');
}

function predEdges(pred) {
  var out = [];
  Object.keys(pred || {}).forEach(function (v) {
    if (pred[v]) out.push(pred[v] + '>' + v);
  });
  return out;
}

function drawEdge(parent, e, color, width, marker, opacity) {
  var p = parent.path(e.path).fill('none').stroke({
    color: color || '#000',
    width: width || 1.5,
    linecap: 'round',
    linejoin: 'round'
  }).opacity(opacity == null ? 1 : opacity);
  if (marker) p.marker('end', arrowMarker);
  p.css('cursor', 'pointer')
    .on('mousemove', function (ev) { showTooltip(e.u + '→' + e.v + ', weight ' + fmt(e.w), ev); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Relax edge ' + e.u + '→' + e.v,
        'Relaxation tests whether d[' + e.u + '] + ' + fmt(e.w) + ' is smaller than d[' + e.v + ']. If it is, the destination estimate and predecessor are updated.');
    });
  return p;
}

function addText(parent, text, x, y, size, opts) {
  opts = opts || {};
  var t = parent.text(text).font({
    family: opts.family || 'Times New Roman, serif',
    size: size,
    style: opts.italic ? 'italic' : 'normal',
    anchor: opts.anchor || 'middle',
    leading: 1
  }).fill(opts.fill || '#000');
  if (opts.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': opts.halo, 'stroke-linejoin': 'round' });
  if (opts.anchor === 'start') t.move(x, y); else t.center(x, y);
  return t;
}

function drawPanel(parent, frame, options) {
  options = options || {};
  var g = parent.group();
  var dist = frame.dist || {};
  var pred = frame.pred || {};
  var active = frame.activeEdge || null;
  var activeKey = active ? active[0] + '>' + active[1] : null;
  var wrongFinal = options.wrongFinal;
  var fontScale = options.fontScale || 1;

  var back = g.group();
  predEdges(pred).forEach(function (key) {
    var e = edgeMap[key];
    if (e) drawEdge(back, e, '#adadad', options.overview ? 7.5 : 8.5, false, 0.92);
  });
  if (!options.overview && activeKey && edgeMap[activeKey]) {
    drawEdge(back, edgeMap[activeKey], frame.status === 'improved' ? '#9f9f9f' : '#d2d2d2', frame.status === 'improved' ? 10 : 7, false, 0.82);
  }

  var edgeLayer = g.group();
  edges.forEach(function (e) { drawEdge(edgeLayer, e, '#000', options.overview ? 1.45 : 1.6, true, 1); });

  var weightLayer = g.group();
  edges.forEach(function (e) {
    addText(weightLayer, fmt(e.w), e.label[0], e.label[1], 22 * fontScale, { halo: options.overview ? 1.2 : 2 });
  });

  var nodeLayer = g.group();
  ['s', 't', 'y', 'x', 'z'].forEach(function (id) {
    var n = nodes[id];
    var bad = wrongFinal && !isExpectedNode(id, dist, pred);
    nodeLayer.circle(48).center(n.x, n.y).fill(bad ? '#ffd7d7' : '#d9d9d9').stroke({ color: '#000', width: 1.25 });
    addText(nodeLayer, fmt(dist[id]), n.x, n.y + 1, 24 * fontScale, { halo: 0 });
    addText(nodeLayer, id, n.ext[0], n.ext[1], 22 * fontScale, { italic: true, halo: 2 });
    nodeLayer.last().css('cursor', 'pointer')
      .on('mousemove', function (ev) { showTooltip('vertex ' + id + ': d[' + id + '] = ' + fmt(dist[id]), ev); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Vertex ' + id, 'The number inside the vertex is the current best distance estimate from source s. Bellman-Ford allows this number to decrease when a better path is discovered.');
      });
  });

  addText(g, frame.panel || '', 168, 282, 25 * fontScale, { halo: 0 });
  return g;
}

